import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'

import "../../scss/main.scss"

import Header from "../../components/Header"
import Footer from "../../components/Footer"
import AccentDots from "../../components/AccentDots"
import Seo from "../../components/Seo"

interface ImageNode {
  name: string
  childImageSharp: {
    thumb: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    images: { nodes: ImageNode[] }
    logo: { nodes: ImageNode[] }
  }
}

const techStack = [
  'JavaScript', 'jQuery', 'HTML5', 'CSS3', 'Adobe Illustrator'
]

const CirclesGamePage: React.FC<PageProps> = ({ data }) => {
  const [spotlightIndex, setSpotlightIndex] = React.useState<number | null>(null)
  const [dragY, setDragY] = React.useState(0)
  const [isDragging, setIsDragging] = React.useState(false)
  const [zoomScale, setZoomScale] = React.useState(1)
  const [zoomOrigin, setZoomOrigin] = React.useState({ x: 50, y: 50 })
  const initialPinchDistance = React.useRef(0)
  const lastScale = React.useRef(1)
  const touchStartY = React.useRef(0)

  const logo = data.logo.nodes[0] ? getImage(data.logo.nodes[0].childImageSharp.thumb) : null
  const screenshot = data.images.nodes.find(n => n.name === 'screen')
  const spotlightImages = screenshot ? [screenshot] : []

  const dismissThreshold = 120

  const getPinchDistance = (touches: React.TouchList) => {
    const dx = touches[0].clientX - touches[1].clientX
    const dy = touches[0].clientY - touches[1].clientY
    return Math.sqrt(dx * dx + dy * dy)
  }

  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      initialPinchDistance.current = getPinchDistance(e.touches)
      lastScale.current = zoomScale
    } else if (e.touches.length === 1 && zoomScale <= 1) {
      touchStartY.current = e.touches[0].clientY
      setIsDragging(true)
    }
  }

  const handleTouchMove = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      const dist = getPinchDistance(e.touches)
      const scale = Math.max(1, Math.min(4, lastScale.current * (dist / initialPinchDistance.current)))
      const midX = ((e.touches[0].clientX + e.touches[1].clientX) / 2 / window.innerWidth) * 100
      const midY = ((e.touches[0].clientY + e.touches[1].clientY) / 2 / window.innerHeight) * 100
      setZoomScale(scale)
      setZoomOrigin({ x: midX, y: midY })
    } else if (e.touches.length === 1 && zoomScale <= 1) {
      const delta = e.touches[0].clientY - touchStartY.current
      if (delta > 0) {
        setDragY(delta)
      }
    }
  }

  const handleTouchEnd = () => {
    if (zoomScale <= 1) {
      setIsDragging(false)
      if (dragY > dismissThreshold) {
        setSpotlightIndex(null)
        setZoomScale(1)
      }
      setDragY(0)
    }
  }

  return (
    <div className="container">
      <Header />

      <div className="case-study__hero">
        <Link to="/developer" className="back-link">&larr; Back to Developer</Link>
        <h1>Circles Game</h1>
        {logo && (
          <div className="case-study__logo-wrap">
            <GatsbyImage image={logo} alt="Circles Game logo" className="case-study__logo" />
          </div>
        )}
        <AccentDots />
      </div>

      <div className="case-study__body">
        <section className="case-study__section">
          <h2>The Game</h2>
          <p>
            A completely visual memory game. The computer displays a sequence of
            coloured circles on a grid, giving the player a few seconds to memorise
            their positions and order. The player then has to click the grid in the
            exact same positions and sequence.
          </p>
          <p>
            Built during the General Assembly Web Development Immersive course.
          </p>
        </section>

        <section className="case-study__section">
          <h2>How to Play</h2>
          <ul className="case-study__stories">
            <li>The computer displays random circles in a grid for a few seconds</li>
            <li>The player clicks the exact position and correct order of the circles</li>
            <li>Correct sequence scores a point for the player, incorrect gives the computer a point</li>
            <li>First to 10 points wins the game</li>
          </ul>
        </section>

        <section className="case-study__section">
          <h2>Design</h2>
          <p>
            The circles are held in a 5&times;5 grid. The colours randomly change each
            turn to make it harder to memorise. The grid sits on a white background so
            the colours really stand out. The logo is the only other dominant visual
            presence, with a simple counter at the bottom of the page.
          </p>
          <p>
            All visual assets including the logo and circle artwork were designed
            and created in Adobe Illustrator.
          </p>
        </section>

        {screenshot && (() => {
          const img = getImage(screenshot.childImageSharp.thumb)
          return img ? (
            <section className="case-study__section">
              <h2>Screenshot</h2>
              <div className="case-study__image-wrap" onClick={() => setSpotlightIndex(0)}>
                <GatsbyImage image={img} alt="Circles Game screenshot" className="case-study__image" />
              </div>
            </section>
          ) : null
        })()}

        <section className="case-study__section">
          <h2>Tech Stack</h2>
          <div className="case-study__pills">
            {techStack.map((tech) => (
              <span key={tech} className="case-study__pill">{tech}</span>
            ))}
          </div>
        </section>

        <section className="case-study__section">
          <h2>Future Aims</h2>
          <ul className="case-study__stories">
            <li>Create vector drawings for the circles to make it more visually interesting</li>
            <li>Add sound effects for the circles</li>
          </ul>
        </section>
      </div>

      {spotlightIndex !== null && (() => {
        const node = spotlightImages[spotlightIndex]
        const image = getImage(node.childImageSharp.thumb)
        const opacity = Math.max(0.2, 1 - dragY / 400)

        return (
          <div
            className="case-study__spotlight"
            onClick={() => { setSpotlightIndex(null); setZoomScale(1) }}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
            style={{ background: `rgba(0, 0, 0, ${opacity * 0.9})` }}
          >
            <div className="case-study__spotlight-hint">Swipe down to close · Pinch to zoom</div>
            <div
              className="case-study__spotlight-content"
              onClick={(e) => {
                e.stopPropagation()
                if (zoomScale > 1) setZoomScale(1)
              }}
              style={{
                transform: `translateY(${dragY}px) scale(${zoomScale})`,
                transformOrigin: `${zoomOrigin.x}% ${zoomOrigin.y}%`,
                transition: isDragging ? 'none' : 'transform 0.3s ease',
              }}
            >
              {image && (
                <GatsbyImage
                  image={image}
                  alt="Circles Game screenshot"
                  className="case-study__spotlight-image"
                />
              )}
            </div>
          </div>
        )
      })()}

      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query CirclesGameQuery {
    images: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "circles-game" }
        extension: { in: ["png", "jpg", "jpeg"] }
        name: { ne: "colour_game_logo_small" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        name
        childImageSharp {
          thumb: gatsbyImageData(width: 800, placeholder: BLURRED)
        }
      }
    }
    logo: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "circles-game" }
        name: { eq: "colour_game_logo_small" }
      }
    ) {
      nodes {
        name
        childImageSharp {
          thumb: gatsbyImageData(width: 200, placeholder: BLURRED)
        }
      }
    }
  }
`

export const Head = () => <Seo title="Circles Game" description="An interactive circles game." />

export default CirclesGamePage
